<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-content-8 {"imageUrl":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/km_svc_01.webp","imageAlt":"新しくなったキッチンと洗面まわり","bgColor":"#ffffff","minHeight":320} -->
<div class="wp-block-wdl-lw-pr-content-8 lw-pr-content-8" style="--content-8-max-w:1040px;--content-8-bdr-pc:10px;--content-8-bdr-sp:10px;--content-8-min-h:320px;background:#ffffff;border:2px solid var(--color-main)"><div class="image"><img loading="lazy" src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/km_svc_01.webp" alt="新しくなったキッチンと洗面まわり"/></div><div class="content_in"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"20px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}}} -->
<h3 style="font-size:20px;line-height:1.6;margin-top:0px;margin-bottom:16px">水まわりの改修</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p style="margin-top:0px;margin-bottom:0px">キッチン・浴室・洗面・トイレ。<span class="lw-br on_500px"></span>1か所だけでもお受けします。設備はメーカーの品番でお選びいただけますが、「どれがいいか分からない」という方には、価格帯ごとに実物をお見せしてから決めていただきます。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"16px","bottom":"0px"}}}} -->
<p style="margin-top:16px;margin-bottom:0px">住みながらの工事もできます。水が止まるのは実際に入れ替える半日ほどで、その日程は必ず事前にお伝えします。</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-content-8 -->
<!-- wp:wdl/lw-pr-content-8 {"imageUrl":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/km_svc_02.webp","imageAlt":"無垢の床板を張っている職人の手元","bgColor":"#ffffff","minHeight":320} -->
<div class="wp-block-wdl-lw-pr-content-8 lw-pr-content-8" style="--content-8-max-w:1040px;--content-8-bdr-pc:10px;--content-8-bdr-sp:10px;--content-8-min-h:320px;background:#ffffff;border:2px solid var(--color-main)"><div class="image"><img loading="lazy" src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/km_svc_02.webp" alt="無垢の床板を張っている職人の手元"/></div><div class="content_in"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"20px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}}} -->
<h3 style="font-size:20px;line-height:1.6;margin-top:0px;margin-bottom:16px">内装・床と壁</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p style="margin-top:0px;margin-bottom:0px">床の張り替え、壁紙、漆喰、間取りの変更まで。素材はカタログではなく実物のサンプルをお持ちします。同じ「白い壁紙」でも部屋の明るさで見え方が変わるので、その場で壁に当てて選んでいただきます。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"16px","bottom":"0px"}}}} -->
<p style="margin-top:16px;margin-bottom:0px">壁を抜きたいというご相談は、<span class="lw-br on_500px"></span>構造をみてからのお返事になります。抜けない柱のときは、その理由と代わりの案をお出しします。</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-content-8 -->
<!-- wp:wdl/lw-pr-content-8 {"imageUrl":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/km_svc_03.webp","imageAlt":"塗り替えたばかりの外壁と軒先","bgColor":"#ffffff","minHeight":320} -->
<div class="wp-block-wdl-lw-pr-content-8 lw-pr-content-8" style="--content-8-max-w:1040px;--content-8-bdr-pc:10px;--content-8-bdr-sp:10px;--content-8-min-h:320px;background:#ffffff;border:2px solid var(--color-main)"><div class="image"><img loading="lazy" src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/km_svc_03.webp" alt="塗り替えたばかりの外壁と軒先"/></div><div class="content_in"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"20px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}}} -->
<h3 style="font-size:20px;line-height:1.6;margin-top:0px;margin-bottom:16px">外壁・屋根</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p style="margin-top:0px;margin-bottom:0px">塗装・張り替え・雨漏りの修理。足場を組む工事のときは、屋根・雨樋・ベランダの防水まで一緒に点検します。足場代はもう一度組むと同じだけかかるので、まとめたほうが結局は安く済みます。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"16px","bottom":"0px"}}}} -->
<p style="margin-top:16px;margin-bottom:0px">雨漏りは原因の特定に時間をいただくことがあります。「たぶんここ」で塗ってしまうと止まらないためです。</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-content-8 -->
<!-- wp:wdl/lw-pr-content-8 {"imageUrl":"https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/km_svc_04.webp","imageAlt":"壁を開けて断熱材を入れているところ","bgColor":"#ffffff","minHeight":320} -->
<div class="wp-block-wdl-lw-pr-content-8 lw-pr-content-8" style="--content-8-max-w:1040px;--content-8-bdr-pc:10px;--content-8-bdr-sp:10px;--content-8-min-h:320px;background:#ffffff;border:2px solid var(--color-main)"><div class="image"><img loading="lazy" src="https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/km_svc_04.webp" alt="壁を開けて断熱材を入れているところ"/></div><div class="content_in"><!-- wp:heading {"level":3,"style":{"typography":{"fontSize":"20px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}}} -->
<h3 style="font-size:20px;line-height:1.6;margin-top:0px;margin-bottom:16px">断熱・耐震</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p style="margin-top:0px;margin-bottom:0px">寒さ・暑さ・地震への備え。<span class="lw-br on_500px"></span>内窓・床下断熱・壁の断熱・耐震の補強まで。国や自治体の補助金が使えることが多い工事なので、申請のお手伝いまで含めてご案内します。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"spacing":{"margin":{"top":"16px","bottom":"0px"}}}} -->
<p style="margin-top:16px;margin-bottom:0px">まず「どこから熱が逃げているか」を見ます。窓が原因なのに壁を触っても効き目が薄く、費用だけがかかるためです。</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-content-8 -->
<!-- wp:paragraph {"align":"center"} -->
<p class="has-text-align-center">※ 上に無い工事（外構・造作家具・店舗の改装など）もお受けしています。<span class="lw-br on_500px"></span>まずはお尋ねください。</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-bg-1 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-custom-title-15 {"mainTitle":"できること","subTitle":"ABOUT US","headingLevel":2} -->
<h2 class="wp-block-wdl-lw-pr-custom-title-15 lw-pr-custom-title-15" style="--custom-title-sub-margin-top-pc:0.2em;--custom-title-sub-margin-top-sp:0.2em;--title-15-after-color:var(--color-main);--title-15-after-mt-pc:1em;--title-15-after-mt-sp:0.8em;--title-15-after-h-pc:4px;--title-15-after-h-sp:4px;--title-15-after-w-pc:50px;--title-15-after-w-sp:50px;--title-15-font-size_pc:16px;--title-15-font-size_sp:16px"><span class="main">できること</span><span class="sub">ABOUT US</span></h2>
<!-- /wp:wdl/lw-pr-custom-title-15 -->
<!-- wp:paragraph {"align":"center"} -->
<p class="has-text-align-center">線を引いておいたほうが、<span class="lw-br on_500px"></span>お互いに時間を無駄にしません。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-space-1 {"pcHeight":40,"tbHeight":32,"spHeight":24} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:40px"></div><div class="tb" style="height:32px"></div><div class="sp" style="height:24px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/paid-block-lw-company-3 {"maxWidth":900,"fontSizeClass":"font_size_m","dtWidthClass":"dt_width_m","spFullDt":true,"dtBackgroundColor":"color-mix(in srgb, var(--color-main) 50%, #000)","borderColor":"color-mix(in srgb, var(--color-main) 50%, #000)","lineHeight":1.7} -->
<div class="wp-block-wdl-paid-block-lw-company-3 paid-block-lw-company-3 font_size_m"><dl class="lw-company-3__inner" style="max-width:900px;line-height:1.7"><div class="lw-company-3__row dt_width_m sp_clm_1"><dt class="lw-company-3__dt" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"><div class="lw-company-3__dt_text" data-lw_font_set="Murecho" style="font-weight:600;line-height:1.7">得意なこと</div><div class="lw-company-3__dt_arrow" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"></div></dt><dd class="lw-company-3__dd" data-lw_font_set="" style="border-color:color-mix(in srgb, var(--color-main) 50%, #000);line-height:1.7">築20年から40年の木造住宅の改修です。創業から手がけてきた棟数がいちばん多く、傷みやすい場所が先に分かります</dd></div><div class="lw-company-3__row dt_width_m sp_clm_1"><dt class="lw-company-3__dt" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"><div class="lw-company-3__dt_text" data-lw_font_set="Murecho" style="font-weight:600;line-height:1.7">小さな工事</div><div class="lw-company-3__dt_arrow" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"></div></dt><dd class="lw-company-3__dd" data-lw_font_set="" style="border-color:color-mix(in srgb, var(--color-main) 50%, #000);line-height:1.7">手すり1本、網戸1枚から伺います。「こんなことで呼んでいいのか」と言われることが多いのですが、まったく構いません</dd></div><div class="lw-company-3__row dt_width_m sp_clm_1"><dt class="lw-company-3__dt" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"><div class="lw-company-3__dt_text" data-lw_font_set="Murecho" style="font-weight:600;line-height:1.7">急ぎの工事</div><div class="lw-company-3__dt_arrow" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"></div></dt><dd class="lw-company-3__dd" data-lw_font_set="" style="border-color:color-mix(in srgb, var(--color-main) 50%, #000);line-height:1.7">水漏れ・雨漏り・鍵の不具合は、ご連絡をいただいたその日のうちに動きます。応急の処置だけでも先に行います</dd></div><div class="lw-company-3__row dt_width_m sp_clm_1"><dt class="lw-company-3__dt" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"><div class="lw-company-3__dt_text" data-lw_font_set="Murecho" style="font-weight:600;line-height:1.7">できない事</div><div class="lw-company-3__dt_arrow" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"></div></dt><dd class="lw-company-3__dd" data-lw_font_set="" style="border-color:color-mix(in srgb, var(--color-main) 50%, #000);line-height:1.7">マンションの専有部の大規模な改修と、鉄骨・鉄筋の建物の構造にかかわる工事はお受けしていません。無理に受けても良い仕事にならないためです</dd></div><div class="lw-company-3__row dt_width_m sp_clm_1"><dt class="lw-company-3__dt" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"><div class="lw-company-3__dt_text" data-lw_font_set="Murecho" style="font-weight:600;line-height:1.7">お断り</div><div class="lw-company-3__dt_arrow" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"></div></dt><dd class="lw-company-3__dd" data-lw_font_set="" style="border-color:color-mix(in srgb, var(--color-main) 50%, #000);line-height:1.7">「今日中に決めてくれたら安くします」という進め方はしません。こちらから催促のご連絡をすることもありません</dd></div><div class="lw-company-3__row dt_width_m sp_clm_1"><dt class="lw-company-3__dt" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"><div class="lw-company-3__dt_text" data-lw_font_set="Murecho" style="font-weight:600;line-height:1.7">他社の工事</div><div class="lw-company-3__dt_arrow" style="background:color-mix(in srgb, var(--color-main) 50%, #000)"></div></dt><dd class="lw-company-3__dd" data-lw_font_set="" style="border-color:color-mix(in srgb, var(--color-main) 50%, #000);line-height:1.7">他社さんが手を入れた箇所の手直しは、状況を見てからのお返事になります。原因が分からないまま上から直すことはできません</dd></div></dl></div>
<!-- /wp:wdl/paid-block-lw-company-3 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-bg-1 {"backgroundType":"image","imagePc":"","imageSp":"","isFullWidth":true,"maxWidth":1040,"minHeightPc":"min-h-pc-150px","minHeightTb":"min-h-tb-160px","minHeightSp":"min-h-sp-160px","innerPaddingTopPc":80,"innerPaddingBottomPc":80,"innerPaddingLeftPc":40,"innerPaddingRightPc":40,"innerPaddingTopTb":64,"innerPaddingBottomTb":64,"innerPaddingLeftTb":32,"innerPaddingRightTb":32,"innerPaddingTopSp":48,"innerPaddingBottomSp":48,"innerPaddingLeftSp":20,"innerPaddingRightSp":20,"filterTypePc":"solid","filterColorPc":"var(--color-main)","opacityPc":0.08,"filterTypeTb":"solid","filterColorTb":"var(--color-main)","opacityTb":0.08,"filterTypeSp":"solid","filterColorSp":"var(--color-main)","opacitySp":0.08} -->
